    Lemma aatexit_tab_size : forall two, Z.of_nat (cells_size (aatexit_tab two)) = 544.
    Proof. intros [|]; reflexivity. Qed.
    Lemma atr_cells_of_adrv : forall m, cells_ok m (adrv_cells true) -> cells_ok m atr_cells.
    Proof.
      intros m CE. unfold adrv_cells, adrv_atexit_cells, cells_ok in CE. apply Forall_app in CE as [C1 C2].
      unfold atr_cells, cells_ok. apply Forall_app. split; [exact C1|].
      inversion C2 as [|x1 l1 X1 C3]; subst. inversion C3 as [|x2 l2 X2 C4]; subst. inversion C4 as [|x3 l3 X3 C5]; subst.
      repeat constructor; assumption.
    Qed.
