    Lemma blk_harness : forall sx LB1 m0 m1 XS q Bk n,
      as_RHEAP H sx LB1 m0 -> In (q, Bk, n) LB1 -> as_RFS H [] m1 -> Forall (fs_scratch H []) XS ->
      Forall (fun iv : Z * Z => Bk + n <= fst iv \/ snd iv <= Bk) (AXH_X ++ XS)
