      (* [comment removed for export] *)
      Lemma lb_remove_perm : forall L q Ak n, List.NoDup (map blk_id L) -> In (q, Ak, n) L ->
        Permutation L ((q, Ak, n) :: as_lb_remove H q L).
      Proof.
        destruct (ah_lb_remove H HH) as (L1 & L2 & L3).
        induction L as [|b L IH]; intros q Ak n ND HIn; [destruct HIn|].
        inversion ND as [|x l Hni Hnd]; subst.
        destruct HIn as [-> | HIn].
        - rewrite (L1 q Ak n L Hni). apply Permutation_refl.
        - assert (NE : blk_id b <> q).
          { intros E. apply Hni. rewrite E. replace q with (blk_id (q, Ak, n)) by reflexivity. apply in_map. exact HIn. }
          rewrite (L2 q b L NE). eapply Permutation_trans; [apply perm_skip; apply (IH q Ak n Hnd HIn) | apply perm_swap].
      Qed.

      Let TRC : adrv_traces H. Proof. exact (atr_tr _ _ _ _ _ _ _ _ _ _ _ _ PRE). Qed.
      Let HCAP : Z.of_nat (length data) <= cap. Proof. exact (atr_cap _ _ _ _ _ _ _ _ _ _ _ _ PRE). Qed.
      Let HAL0 : atr_cost H data <= as_AL H s0. Proof. exact (atr_al _ _ _ _ _ _ _ _ _ _ _ _ PRE). Qed.
      Let COSTS : cost_laws H. Proof. exact (ah_costs H HH). Qed.
Scheme kc__11 := Elimination for OSSVerify.Proofs.boost_beast.http_request.lib.As.AsTargetRun.TR.Call.Loop.lstate Sort Prop.

      (* [comment removed for export] *)
      Lemma tr_free : forall regs m msF mo sC LBc,
        as_VIS H sC msF = mkst regs (Z_to_bv 64 0x0a307c) m rom -> as_AKREL H sC (mkCfg msF mo) ->
        lstate calls calls 1 regs m mo sC LBc -> getr regs 19 = Z_to_bv 64 0 ->
