        lstate k (S k) r regs m mo sC LBc ->
        getr regs 1 = Z_to_bv 64 0x0a307c -> getr regs 11 = Z_to_bv 64 0 -> getr regs 19 = Z_to_bv 64 0 ->
        (forall regs' m' msF' mo',
           as_VIS H sC msF' = mkst regs' (Z_to_bv 64 0x0a307c) m' rom -> as_AKREL H sC (mkCfg msF' mo') ->
           lstate (S k) (S k) r regs' m' mo' sC LBc -> getr regs' 19 = Z_to_bv 64 0 ->
           realizes asegs (mkCfg msF' mo') Kx) ->
        realizes asegs (mkCfg msF mo) Kx.
