    Lemma calls_of_hdr : forall c, nth 2 data (Z_to_bv 8 0) = c -> Z.of_nat calls = calls_of cfg c.
    Proof.
      intros c Hc. subst calls cfg. unfold hdr_calls, calls_of, hdr_b. rewrite Hc. pose proof (hdr_cfg_range data) as HR.
      pose proof (bv_unsigned_in_range 8 c) as H8. unfold bv_modulus in H8. cbn in H8.
      destruct (Z.eqb_spec (hdr_cfg data) 0) as [E|E].
      - rewrite E. reflexivity.
      - destruct (Z.to_nat (hdr_cfg data)) eqn:EN; [lia|].
        replace (Z.land (bv_unsigned c) 3) with (bv_unsigned c mod 4)%Z by (symmetry; apply (Z.land_ones (bv_unsigned c) 2); lia).
        pose proof (Z.mod_pos_bound (bv_unsigned c) 4 ltac:(lia)). lia.
    Qed.

    (* [comment removed for export] *)
    Definition aatexit_fix_cells : list (Z * nat * Z) :=
      [(0x67d500, 1%nat, 0); (0x67d504, 4%nat, 0); (0x67d508, 4%nat, 2); (0x67d510, 8%nat, 0x67d518); (0x67d518, 8%nat, 0);
       (0x67d520, 8%nat, 0x0ff258); (0x67d528, 8%nat, 0x0ff258); (0x67d620, 8%nat, 0x092730); (0x67d628, 8%nat, 0x0a30f8)]%Z.
    Definition aatexit_bytes2 : list byte := Eval vm_compute in cells_bytes (aatexit_tab true).
    Lemma aatexit_tab2_bytes : cells_bytes (aatexit_tab true) = aatexit_bytes2 /\ length aatexit_bytes2 = 544%nat /\ cells_wf (aatexit_tab true).
    Proof. vm_compute. repeat split; reflexivity. Qed.
    Lemma aatexit_cells_fix : forall m, rw_cells asegs m A_ATEXIT (aatexit_tab true) -> cells_ok m aatexit_fix_cells.
    Proof.
      intros m RC. destruct aatexit_tab2_bytes as (B & L & W).
      destruct RC as [[_ BA] _]. rewrite B in BA.
      unfold aatexit_fix_cells, cells_ok.
      repeat (apply Forall_cons; [unfold cell_ok;
        lazymatch goal with |- ?f ?sg ?mm (Z_to_bv 64 ?a) ?n = Some ?v =>
          let k := eval vm_compute in (Z.to_nat (a - A_ATEXIT)) in
          let R := fresh "R" in
          pose proof (OSSVerify.Proofs.boost_beast.http_request.lib.Lib.Mem.bytes_at_rdn asegs m A_ATEXIT aatexit_bytes2 k n BA ltac:(rewrite L; cbn; lia)) as R;
          replace (OSSVerify.Proofs.boost_beast.http_request.lib.Lib.Mem.wa (A_ATEXIT + Z.of_nat k)) with (Z_to_bv 64 a) in R
            by (rewrite OSSVerify.Proofs.boost_beast.http_request.lib.MainMem.wa_eq; f_equal; reflexivity);
          etransitivity; [exact R | vm_compute; reflexivity] end |]).
      apply Forall_nil.
    Qed.

    Lemma cell_ok_munch : forall W m m' a w v,
      cell_ok m (a, w, v) -> munch W m m' -> 0 <= a -> a + Z.of_nat w <= 2 ^ 64 -> disjoint_from W a (Z.of_nat w) -> cell_ok m' (a, w, v).
    Proof.
      intros W m m' a w v C MU Ha Hw D. unfold cell_ok in *. eapply rdn_munch; [exact MU | exact C | lia | lia |].
      intros y Hy. eapply disjoint_outside; [exact D | lia].
    Qed.

