    Lemma aatexit_call : forall (regs : bvmap 5 word) (mem : mem) (msF : machine_state) (mo : Model) (s : as_St H)
        (fn lo f1 a1v nx f0 a0 : Z) (f3 pad fj aj : list byte) (ra : Z) (Kx : TSet),
      as_VIS H s msF = mkst regs (Z_to_bv 64 P_ATEXIT) mem rom -> as_AKREL H s (mkCfg msF mo) ->
      getr regs 1 = Z_to_bv 64 ra -> 0 <= ra < 2 ^ 64 -> ra mod 2 = 0 ->
      getr regs 10 = Z_to_bv 64 fn -> 0 <= fn < 2 ^ 64 ->
      rw_cells asegs mem A_ATEXIT (AtexitCells 1 f1 a1v f3 pad nx f0 fj a0 aj) ->
      bytes_at asegs mem A_NEED_LOCKS [b8 0] ->
      stk asegs mem lo (bv_unsigned (getr regs 2)) -> lo + ATEXIT_FRAME <= bv_unsigned (getr regs 2) -> AIMG_TOP <= lo ->
      mem_inv asegs mem ->
      (forall regs' mem' msF' mo',
         as_VIS H s msF' = mkst regs' (Z_to_bv 64 ra) mem' rom -> as_AKREL H s (mkCfg msF' mo') -> as_MPRES H mo mo' ->
         (forall r, In r aheap_kept -> getr regs' r = getr regs r) -> getr regs' 10 = Z_to_bv 64 0 ->
         munch [(lo, bv_unsigned (getr regs 2)); (A_ATEXIT, A_ATEXIT + 544)]%Z mem mem' -> wmono asegs mem mem' -> mem_inv asegs mem' ->
         stk asegs mem' lo (bv_unsigned (getr regs 2)) ->
         rw_cells asegs mem' A_ATEXIT (AtexitCells 2 P_ATEXIT_CALL fn f3 pad nx f0 fj a0 aj) ->
         realizes asegs (mkCfg msF' mo') Kx) ->
      realizes asegs (mkCfg msF mo) Kx.
