  (* [comment removed for export] *)
  Theorem as_target_run_with : as_target_run_stmt H.
  Proof.
    intros sp A cap data p s LB msF mo regs mem K PRE K0 HPOST.
    exact (as_target_run_ok sp A cap data p s LB msF mo regs mem PRE K K0 HPOST).
  Qed.
End TR.

(* [comment removed for export] *)
Theorem as_target_run {HCEIL : HeapCeil} : forall H : asr,
  asan_rt_hyps H -> asan_driver_laws H -> afuzz_stmt H -> as_target_run_stmt H.
Proof.
  intros H HH DL (HS & HSL & HSI & FZ). exact (as_target_run_with H HH DL HS HSL HSI FZ).
Qed.
